import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import {copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
import {useEffect} from 'react'

import {
  type ContentPreviewContext,
  makeItemFromFileDiffReference,
} from '../components/ContentPreview/content-preview-types'

export function useLoadDiffReferences({updateItem, openItem, openPreviewPane}: ContentPreviewContext) {
  useEffect(() => {
    if (!copilotFeatureFlags.copilotRedirectDiffViewToImmersive) return

    const fileDiffReferences = copilotLocalStorage.getCopilotDiffReferences()
    if (!fileDiffReferences) return

    if (fileDiffReferences.length === 0) return

    for (const reference of fileDiffReferences) {
      const fileDiff = makeItemFromFileDiffReference(reference)
      updateItem(fileDiff)
      openItem(fileDiff.id)
    }
    openPreviewPane()

    // Clear the localStorage item to avoid loading the same references again
    copilotLocalStorage.removeCopilotDiffReferences()
  }, [updateItem, openItem, openPreviewPane])
}
